/details><details><summary>addTo(map)</summary><div><br><p>将图层添加至 map</p><p>参数：</p><ul><li>map <code>Map</code> map added to</li></ul><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>setZIndex(zIndex)</summary><div><br><p>为layer 设置zIndex</p><p>参数：</p><ul><li>zIndex <code>number</code> layer&#39;s z-index</li></ul><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>getZIndex()</summary><div><br><p>获取layer 的 zIndex</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>getMinZoom()</summary><div><br><p>获取 layer 的 minZoom</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>getMaxZoom()</summary><div><br><p>获取layer 的 maxZoom</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>getOpacity()</summary><div><br><p>获取 layer 的 opacity</p><p>返回：</p><ul><li><code>Number</code></li></ul></div></details><details><summary>setOpacity(op)</summary><div><br><p>设置 layer 的 opacity</p><p>参数：</p><ul><li>op <code>number</code> layer&#39;s opacity</li></ul><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>getMap()</summary><div><br><p>获取图层所在 map</p><p>返回：</p><ul><li><code>Map</code></li></ul></div></details><details><summary>getProjection()</summary><div><br><p>获取 layer 所在map 的 projection</p><p>返回：</p><ul><li><code>CommonProjectionType</code></li></ul></div></details><details><summary>bringToFront()</summary><div><br><p>将图层置顶</p><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>bringToBack()</summary><div><br><p>将图层置底</p><p>返回：</p><ul><li><code>Layer</code> this</li></ul></div></details><details><summary>show()</summary><div><br><p>显示图层</p><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>hide()</summary><div><br><p>隐藏图层</p><p>返回：</p><ul><li><code>Any</code> this</li></ul></div></details><details><summary>isVisible()</summary><div><br><p>